from __future__ import annotations

import json
import os
import shutil
import subprocess
import sys
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
OUTPUT_DIR = TASK_DIR / "outputs"
REPORT_PATH = OUTPUT_DIR / "public_reproduction_report.json"
BUILD_DIR = OUTPUT_DIR / "build"
FIXTURE = TASK_DIR / "fixtures" / "case_v3000.mol"


def _write_report(report: dict[str, object]) -> int:
    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
    REPORT_PATH.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(json.dumps(report, indent=2, sort_keys=True))
    status = report.get("status")
    if status == "workflow_completed":
        return 0
    if status == "pre_fix_expected_failure":
        return 1
    return 2


def _runner_failure(reason: str, details: str = "") -> int:
    return _write_report(
        {
            "status": "runner_failure",
            "reason": reason,
            "details": details[-4000:],
        }
    )


def _tool(name: str) -> str | None:
    return shutil.which(name)


def _run(cmd: list[str], timeout: int) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        cmd,
        cwd=TASK_DIR,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
        timeout=timeout,
        check=False,
    )


def main() -> int:
    if _tool("cmake") is None:
        return _runner_failure("cmake_not_found")
    if _tool(os.environ.get("CXX", "c++")) is None and _tool("g++") is None:
        return _runner_failure("cxx_compiler_not_found")
    if not FIXTURE.exists():
        return _runner_failure("fixture_missing")

    BUILD_DIR.mkdir(parents=True, exist_ok=True)
    configure = _run(
        [
            "cmake",
            "-S",
            str(TASK_DIR / "source"),
            "-B",
            str(BUILD_DIR),
            "-DCMAKE_BUILD_TYPE=Release",
        ],
        timeout=180,
    )
    if configure.returncode != 0:
        return _runner_failure("configure_failed", configure.stdout)

    build = _run(["cmake", "--build", str(BUILD_DIR), "-j2"], timeout=900)
    if build.returncode != 0:
        return _runner_failure("build_failed", build.stdout)

    binary = BUILD_DIR / ("task105_probe.exe" if sys.platform.startswith("win") else "task105_probe")
    if not binary.exists():
        return _runner_failure("probe_missing")

    completed = _run([str(binary), str(FIXTURE)], timeout=60)
    if completed.returncode != 0:
        return _write_report(
            {
                "status": "pre_fix_expected_failure",
                "stage": "canonicalization_workflow",
                "exit_code": completed.returncode,
            }
        )

    return _write_report({"status": "workflow_completed"})


if __name__ == "__main__":
    raise SystemExit(main())
#include <GraphMol/FileParsers/FileParsers.h>
#include <GraphMol/MolStandardize/Tautomer.h>
#include <GraphMol/RDKitBase.h>
#include <GraphMol/SmilesParse/SmilesWrite.h>

#include <fstream>
#include <iostream>
#include <memory>
#include <sstream>
#include <string>

namespace {

std::string read_text(const char *path) {
  std::ifstream input(path);
  if (!input) {
    throw std::runtime_error("input file could not be opened");
  }
  std::ostringstream buffer;
  buffer << input.rdbuf();
  return buffer.str();
}

}  // namespace

int main(int argc, char **argv) {
  if (argc != 2) {
    std::cerr << "usage: task105_probe <molfile>\n";
    return 2;
  }

  const auto molblock = read_text(argv[1]);
  std::unique_ptr<RDKit::RWMol> mol(RDKit::MolBlockToMol(molblock));
  if (!mol) {
    std::cerr << "load=failed\n";
    return 3;
  }

  RDKit::MolStandardize::TautomerEnumerator enumerator;
  enumerator.setRemoveBondStereo(false);

  std::unique_ptr<RDKit::ROMol> canonical(enumerator.canonicalize(*mol));
  const auto serial = RDKit::MolToSmiles(*canonical);
  if (serial.empty()) {
    return 4;
  }

  std::cout << "workflow_complete\n";
  return 0;
}

